-- Layout Award CENIM 2026 (Best Paper / Best Presenter): judul "Certificate", nama + garis emas,
-- nama penghargaan, judul paper penerima (elemen paper), tanda tangan chair + stempel dari Settings.
-- Menimpa layout template Award edisi 2026; PDF tersimpan dibuang supaya memakai layout baru.

UPDATE certificate_templates SET fields_json = '[{"key":"heading","kind":"text","label":"Heading","value":"Certificate","x":50,"y":13.2,"size":58,"bold":true,"align":"C","color":"#033A80","width":80,"hidden":false,"font":"serif"},{"key":"number","kind":"number","label":"Certificate number","value":"No.","x":50,"y":25.6,"size":11,"bold":false,"align":"C","color":"#33415C","width":70,"hidden":false,"font":"sans"},{"key":"intro","kind":"text","label":"Intro line","value":"This certificate is proudly awarded to","x":50,"y":28.6,"size":13,"bold":false,"align":"C","color":"#33415C","width":80,"hidden":false,"font":"sans"},{"key":"name","kind":"name","label":"Recipient name","value":"","x":50,"y":31.6,"size":36,"bold":true,"align":"C","color":"#0B1A3E","width":88,"hidden":false,"font":"sans"},{"key":"gold_line","kind":"line","label":"Gold line","value":"","x":50,"y":40.7,"size":14,"bold":false,"align":"C","color":"#F2B417","width":53,"hidden":false,"font":"sans"},{"key":"affiliation","kind":"affiliation","label":"Affiliation","value":"From","x":50,"y":42.4,"size":13,"bold":false,"align":"C","color":"#0B1A3E","width":86,"hidden":false,"font":"sans"},{"key":"for_line","kind":"text","label":"Reason line","value":"in recognition of the","x":50,"y":47.4,"size":12,"bold":false,"align":"C","color":"#33415C","width":70,"hidden":false,"font":"sans"},{"key":"subject","kind":"subject","label":"Award title","value":"","x":50,"y":50,"size":23,"bold":true,"align":"C","color":"#033A80","width":86,"hidden":false,"font":"sans"},{"key":"paper_line","kind":"text","label":"Paper line","value":"for the paper entitled:","x":50,"y":55.8,"size":12,"bold":false,"align":"C","color":"#33415C","width":70,"hidden":false,"font":"sans"},{"key":"paper","kind":"paper","label":"Paper title","value":"","x":50,"y":58.4,"size":15,"bold":true,"align":"C","color":"#0B1A3E","width":77,"hidden":false,"font":"sans"},{"key":"conference","kind":"text","label":"Conference","value":"The 7th International Conference on Computer Engineering, Network, and Intelligent Multimedia (CENIM 2026)","x":50,"y":66.6,"size":11,"bold":false,"align":"C","color":"#0B1A3E","width":88,"hidden":false,"font":"sans"},{"key":"venue","kind":"text","label":"Venue","value":"Hybrid Conference, 24-25 November 2026, Banyuwangi, Indonesia","x":50,"y":69.6,"size":11,"bold":false,"align":"C","color":"#33415C","width":80,"hidden":false,"font":"sans"},{"key":"place_date","kind":"text","label":"Place and date","value":"Banyuwangi, 25 November 2026\nGeneral Chair,","x":50,"y":74.2,"size":11,"bold":false,"align":"C","color":"#33415C","width":50,"hidden":false,"font":"sans"},{"key":"date","kind":"date","label":"Issue date","value":"","x":50,"y":74.2,"size":11,"bold":false,"align":"C","color":"#33415C","width":50,"hidden":true,"font":"sans"},{"key":"signature","kind":"signature","label":"Signature","value":"","x":50,"y":78.2,"size":40,"bold":false,"align":"C","color":"#000000","width":40,"hidden":false,"font":"sans"},{"key":"signatory","kind":"text","label":"Signatory","value":"","x":50,"y":86.4,"size":11,"bold":true,"align":"C","color":"#0B1A3E","width":40,"hidden":false,"font":"sans"},{"key":"qr","kind":"qr","label":"QR code","value":"","x":14,"y":71,"size":22,"bold":false,"align":"C","color":"#000000","width":22,"hidden":false,"font":"sans"},{"key":"code","kind":"code","label":"Verification code","value":"","x":14,"y":82.2,"size":7,"bold":false,"align":"C","color":"#33415C","width":24,"hidden":false,"font":"sans"}]', updated_at = datetime('now')
WHERE type = 'award' AND edition_id IN (SELECT id FROM editions WHERE year = 2026);

UPDATE certificates SET pdf_cache = NULL
WHERE template_id IN (SELECT t.id FROM certificate_templates t JOIN editions e ON e.id = t.edition_id WHERE t.type = 'award' AND e.year = 2026);
